@import url('https://fonts.googleapis.com/css2?family=Barlow+Condensed:wght@500;600;700;800;900&family=DM+Mono:wght@400;500&family=Manrope:wght@400;500;600;700;800&display=swap');
:root{color-scheme:dark;--bg:#080b11;--panel:#10151e;--panel2:#141a25;--line:#252d3b;--muted:#758196;--white:#f5f7fb;--red:#fa3c50;--lime:#c8f368;--mono:'DM Mono',monospace;--display:'Barlow Condensed',Impact,sans-serif;--body:Manrope,system-ui,sans-serif}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--white);font-family:var(--body);min-height:100vh;background-image:radial-gradient(ellipse at 68% 32%,#19202a 0,transparent 38%),linear-gradient(115deg,#090c12 0%,#0d1119 60%,#090c12 100%)}button,select{font:inherit}button{cursor:pointer;color:inherit}.shell{max-width:1512px;margin:0 auto;padding:0 40px 30px}.topbar{height:82px;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid #ffffff12}.brand{display:flex;align-items:center;gap:12px}.brandmark{width:35px;height:35px;background:var(--red);display:grid;place-items:center;clip-path:polygon(0 0,100% 0,82% 100%,0 100%);font:900 20px var(--display);color:white}.brandname{font:800 17px var(--display);letter-spacing:1.9px}.brandname span{color:var(--red)}.brand-sub{font:9px var(--mono);letter-spacing:2px;color:#7f8999;margin-top:3px}.top-right{display:flex;align-items:center;gap:26px}.season{font:10px var(--mono);letter-spacing:1.5px;color:#929bad}.season b{color:var(--lime);font-weight:500}.season span{color:#495466;margin:0 6px}.season strong{color:white;font-weight:500}.profile{display:flex;align-items:center;gap:10px;border-left:1px solid var(--line);padding-left:22px}.avatar{width:32px;height:32px;border-radius:50%;background:linear-gradient(145deg,#293443,#a04c50);display:grid;place-items:center;font:10px var(--mono)}.profile-name{font:700 10px var(--mono);letter-spacing:1px}.profile-rank{font:8px var(--mono);letter-spacing:1px;color:#7b879a;margin-top:4px}main{padding-top:27px}.intro{display:flex;align-items:end;justify-content:space-between;margin-bottom:19px}.eyebrow,.panel-kicker{display:flex;align-items:center;gap:9px;color:#9da9b9;font:10px var(--mono);letter-spacing:1.8px}.eyebrow-line{width:21px;height:2px;background:var(--red)}.year{color:var(--red)}h1{font:700 39px/1 var(--display);letter-spacing:.3px;margin:9px 0 6px}h1 i{font-style:normal;color:var(--red)}.intro-copy{font-size:11px;color:#818c9d;margin:0;letter-spacing:.15px}.race-status{display:flex;gap:8px;align-items:center;font:9px var(--mono);letter-spacing:1.25px;color:#aab3c0;padding:0 1px 5px}.live-dot{height:7px;width:7px;border-radius:50%;background:var(--lime);box-shadow:0 0 10px #c8f36868;display:inline-block}.layout{display:grid;grid-template-columns:minmax(0,1.73fr) minmax(270px,.83fr);gap:17px}.main-column,.side-column{min-width:0}.track-card,.race-card,.timing-card{background:linear-gradient(145deg,#111720,#0e131b);border:1px solid #ffffff10}.track-top{padding:18px 20px 15px;display:flex;justify-content:space-between;align-items:center;gap:16px}.track-kicker{font:9px var(--mono);color:#929dae;letter-spacing:1.7px}.slash{color:var(--red);padding:0 8px}h2{font:700 25px/1.1 var(--display);letter-spacing:.1px;margin:6px 0 7px}.track-meta{display:flex;align-items:center;gap:10px;color:#8893a4;font:9px var(--mono);letter-spacing:1px}.meta-divider{height:10px;width:1px;background:#3a4351}.track-picker{position:relative;min-width:183px}.track-picker label{display:block;color:#697589;font:8px var(--mono);letter-spacing:1.2px;margin-bottom:5px}.track-picker select{width:100%;height:34px;appearance:none;background:#171e29;border:1px solid #2a3444;border-radius:2px;padding:0 28px 0 10px;color:#e5e9f1;font:10px var(--mono);outline:none}.track-picker select:focus{border-color:#fa3c5080}.select-chev{position:absolute;right:11px;bottom:8px;pointer-events:none;color:#aeb8c7}.map-wrap{height:365px;position:relative;overflow:hidden;background:radial-gradient(ellipse at 50% 50%,#17221d 0%,#111b19 38%,#101720 80%)}canvas{display:block;width:100%;height:100%;touch-action:none}.map-vignette{position:absolute;inset:0;pointer-events:none;background:linear-gradient(90deg,#090e160c,transparent 20%,transparent 80%,#090e1618),linear-gradient(0deg,#090e1628,transparent 20%,transparent 80%,#090e1610)}.map-label{position:absolute;font:8px var(--mono);letter-spacing:1.2px;color:#bcc8bd;background:#0d1414c9;border:1px solid #ffffff15;padding:6px 8px}.start-label{left:16px;bottom:15px}.start-icon{color:var(--lime);margin-right:5px}.north-label{right:15px;top:15px;display:grid;gap:2px;text-align:center;padding:5px 8px;color:#87968c}.north-label span{color:var(--lime);font-size:13px}.track-watermark{position:absolute;top:16px;left:18px;color:#ffffff17;font:900 19px var(--display);letter-spacing:2px;pointer-events:none}.track-watermark span{font:8px var(--mono);color:#ffffff42;letter-spacing:1.4px;margin-left:5px}.countdown{position:absolute;inset:0;display:grid;place-items:center;background:#080b1160;color:white;font:900 95px var(--display);text-shadow:0 0 35px #fa3c5090}.hidden{display:none!important}.finish-overlay{position:absolute;inset:0;background:#080b11dc;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:8px}.finish-overlay .eyebrow{color:var(--lime)}.finish-overlay strong{font:800 48px var(--display);letter-spacing:1px}.finish-overlay>span:not(.eyebrow){font:11px var(--mono);color:#aab5c5}.small-btn{margin-top:8px;padding:9px 15px;background:#19212d;border:1px solid #ffffff22;font:10px var(--mono);letter-spacing:1px}.small-btn span{color:var(--lime);padding-left:12px}.map-legend{height:35px;padding:0 17px;display:flex;justify-content:space-between;align-items:center;border-top:1px solid #ffffff0b;color:#8792a2;font:8px var(--mono);letter-spacing:1.1px}.legend-dot{width:6px;height:6px;border-radius:50%;display:inline-block;margin:0 6px 0 13px}.legend-dot:first-child{margin-left:0}.player-dot{background:var(--red);box-shadow:0 0 7px #fa3c50a0}.ai-dot{background:#d7e5df}.map-coords{color:#687588}.map-coords span{color:var(--red);padding:0 4px}.controls-strip{height:45px;margin-top:9px;border-top:1px solid #ffffff0c;display:flex;align-items:center;gap:14px;color:#8490a2}.control-title{display:flex;align-items:center;gap:7px;font:8px var(--mono);letter-spacing:1px;color:#a0a9b8;padding-right:3px}.keyboard-icon{font-size:14px;color:#b5c0cf}.key-group{display:flex;align-items:center;gap:3px}.key-group kbd,.ers-hint kbd{font:8px var(--mono);color:#d1d7e0;border:1px solid #394251;background:#181f2a;border-radius:2px;padding:3px 5px;min-width:17px;text-align:center}.key-group span{font:7px var(--mono);letter-spacing:.7px;color:#737f92;margin-left:4px;white-space:nowrap}.race-card{padding:17px 17px 13px}.card-head{display:flex;justify-content:space-between;align-items:start}.panel-kicker{font-size:8px;letter-spacing:1.5px;color:#8390a3}h3{font:700 23px var(--display);margin:4px 0 0}.round-chip{font:9px var(--mono);color:var(--red);border:1px solid #fa3c5044;padding:5px 7px}.race-stats{display:grid;grid-template-columns:1fr 1fr;margin:16px -1px 15px;border-top:1px solid #ffffff12;border-bottom:1px solid #ffffff12}.stat{height:55px;display:flex;flex-direction:column;justify-content:center;gap:5px;padding-left:9px}.stat:nth-child(odd){border-right:1px solid #ffffff10}.stat:nth-child(-n+2){border-bottom:1px solid #ffffff10}.stat-label{font:8px var(--mono);letter-spacing:.75px;color:#778396}.stat strong{font:600 16px var(--display);letter-spacing:.3px}.stat strong small{font:8px var(--mono);color:#9aa5b4}.stat .record{font:12px var(--mono);color:var(--lime)}.start-btn{width:100%;height:43px;display:flex;align-items:center;gap:10px;background:var(--red);border:0;padding:0 13px;text-align:left;font:700 12px var(--display);letter-spacing:1.2px;transition:background .16s,transform .16s}.start-btn:hover{background:#ff5062;transform:translateY(-1px)}.start-btn:disabled{opacity:.55;cursor:default;transform:none}.flag-icon{font-size:17px}.button-arrow{font:17px var(--body);margin-left:auto}.race-note{display:flex;align-items:center;gap:7px;color:#778395;font-size:9px;margin-top:11px}.race-note>span:first-child{color:var(--lime)}.timing-card{margin-top:11px;padding:13px 15px 0}.timing-head{display:flex;align-items:center;justify-content:space-between;margin-bottom:8px}.timing-state{display:flex;align-items:center;gap:6px;color:#8792a2;font:8px var(--mono);letter-spacing:.8px}.timing-state .live-dot{width:5px;height:5px;background:#586477;box-shadow:none}.timing-row{display:flex;align-items:center;gap:10px;min-height:39px;border-top:1px solid #ffffff0e}.position{font:700 17px var(--display);color:#a9b4c3;width:24px}.timing-main{display:flex;align-items:center;justify-content:space-between;flex:1;min-width:0}.driver-line{font:700 9px var(--mono);letter-spacing:.7px}.you-tag{margin-left:5px;color:#fa6775;font-size:8px}.gap,.lap-time{font:8px var(--mono);color:#8793a4}.lap-time{min-width:56px;text-align:right}.rival-row{display:flex;align-items:center;gap:10px;min-height:33px;border-top:1px solid #ffffff0b}.rival-pos{width:24px;font:11px var(--display);color:#8290a1}.rival-name{flex:1;font:8px var(--mono);color:#c1c9d4;letter-spacing:.4px}.rival-team{font:7px var(--mono);color:#697589;margin-left:4px}.rival-gap{font:8px var(--mono);color:#788598}.timing-foot{height:29px;display:flex;justify-content:space-between;align-items:center;border-top:1px solid #ffffff12;color:#768294;font:8px var(--mono);letter-spacing:1px}.timing-foot span:last-child{color:#aab5c5}.telemetry{margin-top:13px;background:#10151e;border:1px solid #ffffff10;min-height:81px;display:flex;align-items:center;padding:12px 18px;gap:0}.telemetry-title{display:flex;align-items:center;gap:7px;color:#a8b2c1;font:8px var(--mono);letter-spacing:1.1px;white-space:nowrap;padding-right:19px;border-right:1px solid #ffffff12}.telemetry-dot{height:6px;width:6px;background:var(--lime);border-radius:50%;box-shadow:0 0 8px #c8f36865}.telemetry-sub{font-size:7px;color:#657185;margin-left:3px}.telemetry-item{height:44px;padding:0 17px;border-right:1px solid #ffffff12;display:flex;flex-direction:column;justify-content:space-between;min-width:72px}.tele-label{font:7px var(--mono);letter-spacing:.9px;color:#778397}.telemetry-item strong{font:600 21px var(--display);line-height:1}.telemetry-item small{font:8px var(--mono);color:#8793a5;margin-left:3px}.speed-item{min-width:139px}.speed-item>div:nth-child(2){display:flex;align-items:end}.speed-meter,.ers-meter{height:3px;width:100%;background:#29313d;margin-top:5px}.speed-meter i,.ers-meter i{height:100%;width:0;display:block;background:var(--lime);transition:width .15s}.gear-item{min-width:58px}.gear-item strong{color:var(--lime)}.lap-item{min-width:70px}.time-item{min-width:107px}.time-item strong,.best-item strong{font:11px var(--mono);letter-spacing:.3px}.best-item{min-width:116px;border:0}.ers-item{margin-left:auto;min-width:146px}.ers-head{display:flex;justify-content:space-between;color:#9aa5b5;font:8px var(--mono);letter-spacing:.8px}.ers-head span:last-child{color:var(--lime)}.ers-meter{height:4px;margin:8px 0 6px}.ers-meter i{background:var(--red)}.ers-hint{font:7px var(--mono);color:#687588;letter-spacing:.8px}.ers-hint kbd{font-size:7px;padding:2px 4px;margin-left:4px}footer{display:flex;justify-content:space-between;padding:15px 2px 0;color:#505b6c;font:8px var(--mono);letter-spacing:1px}footer b{color:var(--red);padding:0 3px}.touch-controls{display:none}.paused-banner{position:absolute;inset:0;display:grid;place-items:center;background:#090d15b9;font:800 50px var(--display);letter-spacing:4px;z-index:3}
@media(max-width:1000px){.shell{padding:0 22px 24px}.layout{grid-template-columns:minmax(0,1.6fr) minmax(250px,.85fr);gap:12px}.map-wrap{height:330px}.telemetry{padding:10px}.telemetry-title{padding-right:10px}.telemetry-item{padding:0 10px}.speed-item{min-width:112px}.ers-item{min-width:112px}.controls-strip{gap:8px}.control-title{font-size:7px}.key-group span{font-size:6px}}
@media(max-width:760px){.shell{padding:0 14px 90px}.topbar{height:65px}.top-right{gap:0}.season{font-size:8px;letter-spacing:.6px}.profile{display:none}.intro{margin:19px 0 16px}.intro-copy{font-size:10px}.race-status{font-size:8px}.layout{grid-template-columns:1fr;gap:11px}.track-top{padding:14px 13px 12px;align-items:end}.track-picker{min-width:145px;width:40%}h2{font-size:21px}.track-meta{font-size:8px;gap:7px}.map-wrap{height:min(56vw,350px);min-height:220px}.map-legend{padding:0 12px}.controls-strip{justify-content:space-between;gap:4px;height:39px}.control-title{font-size:0;padding:0}.keyboard-icon{font-size:16px}.key-group{gap:2px}.key-group kbd{font-size:7px;padding:3px 4px;min-width:15px}.key-group span{display:none}.side-column{display:grid;grid-template-columns:1fr 1fr;gap:9px}.race-card{padding:12px}.timing-card{margin-top:0;padding:12px 11px 0}.race-stats{margin:10px -1px}.stat{height:47px}.stat-label{font-size:7px}.stat strong{font-size:14px}.race-note{font-size:8px}.timing-row{gap:6px;min-height:33px}.lap-time{font-size:7px;min-width:49px}.rival-row{gap:6px;min-height:29px}.telemetry{margin-top:10px;flex-wrap:wrap;row-gap:12px;padding:11px 10px;min-height:auto}.telemetry-title{width:100%;border:0;padding:0 0 8px;border-bottom:1px solid #ffffff12}.telemetry-item{padding:0 9px;min-width:unset;flex:1;height:37px}.speed-item{min-width:104px;flex:1.6}.speed-item strong{font-size:20px}.gear-item{flex:.65}.lap-item{flex:.9}.time-item,.best-item{flex:1.25}.time-item strong,.best-item strong{font-size:9px}.ers-item{margin:0;width:100%;min-width:100%}.ers-meter{margin:5px 0}.ers-hint{display:none}footer{font-size:7px}.touch-controls{position:fixed;z-index:10;bottom:max(10px,env(safe-area-inset-bottom));left:50%;transform:translateX(-50%);display:flex;gap:8px;padding:8px;background:#10151ee8;border:1px solid #ffffff1b;border-radius:8px;backdrop-filter:blur(10px)}.touch-controls button{width:48px;height:42px;border:1px solid #ffffff25;border-radius:5px;background:#1a222e;color:#e8edf5;font-size:15px;touch-action:none;user-select:none}.touch-controls button[data-control=gas]{color:var(--lime)}.touch-controls button[data-control=boost]{background:#fa3c50;color:white}.touch-controls button:active,.touch-controls button.active{background:#384355}.touch-controls button[data-control=boost].active{background:#ff6b4d}}
@media(max-width:440px){.shell{padding-left:10px;padding-right:10px}.brandname{font-size:14px}.brand-sub{font-size:7px}.brandmark{width:30px;height:30px}.season{font-size:7px}.track-top{align-items:flex-start;flex-direction:column;gap:9px}.track-picker{width:100%;display:flex;align-items:center;gap:8px}.track-picker label{margin:0;white-space:nowrap}.track-picker select{height:30px}.select-chev{bottom:7px}.track-meta{flex-wrap:wrap;font-size:7px}.side-column{grid-template-columns:1fr}.race-card{padding:13px}.race-stats{margin:12px -1px}.stat{height:49px}.timing-card{padding:12px 14px 0}.rival-row{min-height:29px}.map-wrap{min-height:200px}h1{font-size:34px}.eyebrow{font-size:9px}.intro-copy{max-width:245px}.touch-controls{gap:5px}.touch-controls button{width:44px;height:40px}}

(() => {
const $=id=>document.getElementById(id), canvas=$('gameCanvas'),ctx=canvas.getContext('2d');
const drivers=[{name:'L. VARGAS',team:'VER',color:'#f5c84b',pace:226},{name:'M. KIM',team:'KMR',color:'#54b3e8',pace:232},{name:'A. MOREAU',team:'MTR',color:'#f07b4f',pace:222},{name:'S. PETROV',team:'PTR',color:'#b986f5',pace:230},{name:'J. OKAFOR',team:'OFR',color:'#53d2a3',pace:218},{name:'E. TANAKA',team:'TNA',color:'#e4e9ef',pace:225},{name:'R. SILVA',team:'SVA',color:'#ec78ad',pace:214}];
let trackIndex=0, track, path=[], totalLength=0, state='idle', countdown=0, progress=0, speed=0, lane=0, ers=100, raceTime=0, lapStarted=0, bestLap=Infinity, lastLap=null, flash=0, pausedFrom='race';
const keys={gas:false,brake:false,left:false,right:false,boost:false}, AI=drivers.map((d,i)=>({...d,progress:(drivers.length-i)*.009,lane:(i%3-1)*.27,lapTime:0}));
function makePath(shape){const pts=[];for(let i=0;i<shape.length;i++){const p0=shape[(i-1+shape.length)%shape.length],p1=shape[i],p2=shape[(i+1)%shape.length],p3=shape[(i+2)%shape.length];for(let j=0;j<28;j++){const t=j/28,t2=t*t,t3=t2*t;pts.push({x:.5*((2*p1[0])+(-p0[0]+p2[0])*t+(2*p0[0]-5*p1[0]+4*p2[0]-p3[0])*t2+(-p0[0]+3*p1[0]-3*p2[0]+p3[0])*t3),y:.5*((2*p1[1])+(-p0[1]+p2[1])*t+(2*p0[1]-5*p1[1]+4*p2[1]-p3[1])*t2+(-p0[1]+3*p1[1]-3*p2[1]+p3[1])*t3)});}}
let len=0;pts.forEach((p,i)=>{if(i){const a=pts[i-1];len+=Math.hypot(p.x-a.x,p.y-a.y)}p.d=len});totalLength=len;path=pts;}
function at(p){let d=((p%1)+1)%1*totalLength,lo=0,hi=path.length-1;while(lo<hi){const m=(lo+hi)>>1;if(path[m].d<d)lo=m+1;else hi=m}const b=path[lo],a=path[(lo-1+path.length)%path.length],den=b.d-a.d||1,t=Math.max(0,Math.min(1,(d-a.d)/den)),dx=b.x-a.x,dy=b.y-a.y,n=Math.hypot(dx,dy)||1;return{x:a.x+(b.x-a.x)*t,y:a.y+(b.y-a.y)*t,tx:dx/n,ty:dy/n,nx:-dy/n,ny:dx/n,angle:Math.atan2(dy,dx)}}
function setupTrack(index){trackIndex=index;track=TRACKS[index];makePath(track.shape);$('trackName').textContent=track.name;$('trackCountry').textContent=track.country;$('trackLocation').textContent=track.location;$('trackLength').textContent=track.length+' KM';$('trackTurns').textContent=track.turns+' TURNS';$('trackRecord').textContent=track.record;$('sideLength').innerHTML=track.length+' <small>KM</small>';$('round').textContent=String(index+1).padStart(2,'0');$('roundChip').textContent='R'+String(index+1).padStart(2,'0');$('trackRound').textContent='ROUND '+String(index+1).padStart(2,'0');$('trackSelect').value=String(index);resetRace();}
function resetRace(){state='idle';countdown=0;progress=0;speed=0;lane=0;ers=100;raceTime=0;lapStarted=0;bestLap=Infinity;lastLap=null;AI.forEach((a,i)=>{a.progress=(drivers.length-i)*.009;a.lane=(i%3-1)*.27;a.lapTime=0});$('startLabel').textContent='START RACE';$('startBtn').disabled=false;$('trackSelect').disabled=false;$('statusText').textContent='PIT LANE OPEN';$('timingState').textContent='STANDBY';$('playerTime').textContent='—:—.———';$('currentTime').textContent='00:00.000';$('bestTime').textContent='—:—.———';$('lap').textContent='—';$('speed').textContent='000';$('gear').textContent='N';$('speedMeter').style.width='0%';$('ersMeter').style.width='100%';$('ersPct').textContent='100%';$('finishOverlay').classList.add('hidden');$('countdown').classList.add('hidden');updateStandings();}
function startRace(){if(state==='paused'){resume();return}if(state==='race'){pause();return}if(state==='countdown')return;resetRace();state='countdown';countdown=3.5;$('countdown').textContent='3';$('countdown').classList.remove('hidden');$('startBtn').disabled=true;$('trackSelect').disabled=true;$('statusText').textContent='FORM UP ON THE GRID';$('timingState').textContent='GRID';}
function pause(){if(state!=='race')return;state='paused';$('countdown').textContent='PAUSED';$('countdown').classList.remove('hidden');$('startLabel').textContent='RESUME RACE';$('statusText').textContent='RACE PAUSED';}
function resume(){if(state!=='paused')return;state='race';$('countdown').classList.add('hidden');$('startLabel').textContent='PAUSE RACE';$('statusText').textContent='RACE IN PROGRESS';}
$('startBtn').addEventListener('click',startRace);$('againBtn').addEventListener('click',startRace);
const select=$('trackSelect');TRACKS.forEach((t,i)=>{const o=document.createElement('option');o.value=i;o.textContent=String(i+1).padStart(2,'0')+'  ·  '+t.name;select.append(o)});select.addEventListener('change',()=>setupTrack(+select.value));
function formatTime(seconds){if(!Number.isFinite(seconds)||seconds<0)return'—:—.———';const m=Math.floor(seconds/60),s=seconds%60;return`${String(m).padStart(2,'0')}:${s.toFixed(3).padStart(6,'0')}`}
function updateStandings(){const sorted=[...AI.map(a=>({a,p:a.progress})),{player:true,p:progress}].sort((a,b)=>b.p-a.p);const rank=sorted.findIndex(x=>x.player)+1;$('position').textContent='P'+rank;$('playerGap').textContent=rank===1?'LEADER':`+${Math.max(0,(sorted[0].p-progress)*25).toFixed(1)}s`;$('classified').textContent=`${Math.max(0,Math.floor(progress))} / 8`;
const rivalWrap=$('rivalRows');rivalWrap.innerHTML='';sorted.filter(x=>!x.player).forEach((x,i)=>{const row=document.createElement('div');row.className='rival-row';const gap=Math.abs(x.p-progress)*25;row.innerHTML=`<span class="rival-pos">P${i+(i>=rank?2:1)}</span><span class="rival-name">${x.a.name}<span class="rival-team">${x.a.team}</span></span><span class="rival-gap">${x.p>progress?'+':''}${gap.toFixed(1)}s</span>`;rivalWrap.append(row)});return rank;}
